import React, { useState } from 'react';
import { Navigation, AlertCircle, Database, CheckCircle2, Clock } from 'lucide-react';

const ScheduleTab = ({ onNavigateToReports }) => {
  const [verifyingId, setVerifyingId] = useState(null);

  const schedule = [
    { id: 'LOC_04', time: '08:00', area: 'Sector 4', hasReport: true, status: 'pending', type: 'Biohazard' },
    { id: 'LOC_09', time: '10:30', area: 'Zone B', hasReport: false, status: 'pending', type: 'General' },
    { id: 'LOC_12', time: '13:00', area: 'Plaza SQ', hasReport: false, status: 'done', type: 'Recycle' },
  ];

  return (
    <div className="w-full max-w-md animate-slide-up px-6 py-10">
      <div className="flex justify-between items-end mb-10">
        <h3 className="text-4xl font-[1000] italic text-[#47510B] uppercase tracking-tighter">Manifest.</h3>
        <span className="text-[9px] font-black opacity-30 tracking-[0.3em]">SHIFT_A // 2026</span>
      </div>

      <div className="relative border-l-4 border-[#47510B]/10 ml-4 pl-8 space-y-12">
        {schedule.map((item) => (
          <div key={item.id} className="relative">
            {/* Timeline Node Connector */}
            <div className={`absolute -left-[42px] top-0 w-6 h-6 rounded-full border-4 border-[#FDFAD8] shadow-sm z-10 ${item.status === 'done' ? 'bg-[#CAD23C]' : 'bg-[#47510B]'}`} />

            {/* Minimalist Card */}
            <div className="group relative">
              <div className="flex items-center gap-3 mb-2">
                <Clock size={12} className="text-[#47510B]/40" />
                <span className="text-[10px] font-black text-[#47510B]/40 uppercase tracking-widest">{item.time}</span>
                {item.hasReport && (
                  <button 
                    onClick={onNavigateToReports}
                    className="flex items-center gap-1 bg-[#AB1717] text-white px-2 py-0.5 rounded text-[8px] font-black animate-pulse"
                  >
                    <AlertCircle size={10} /> ISSUE_REPORTED
                  </button>
                )}
              </div>

              <div className={`p-5 rounded-[30px] border-2 transition-all duration-300 flex items-center justify-between ${item.status === 'done' ? 'bg-white/50 border-dashed border-[#47510B]/20' : 'bg-white border-[#47510B] shadow-[6px_6px_0_0_#47510B] hover:-translate-y-1 hover:shadow-[10px_10px_0_0_#CAD23C]'}`}>
                <div>
                  <h4 className={`text-xl font-black uppercase italic leading-none ${item.status === 'done' ? 'opacity-30' : 'text-[#47510B]'}`}>{item.area}</h4>
                  <p className="text-[9px] font-bold opacity-40 mt-1 uppercase tracking-tighter">{item.type} // {item.id}</p>
                </div>

                {item.status === 'done' ? (
                  <CheckCircle2 size={24} className="text-[#CAD23C]" />
                ) : (
                  <div className="flex gap-2">
                    <button onClick={() => setVerifyingId(item.id)} className="p-3 rounded-xl bg-[#FDFAD8] text-[#47510B] border border-[#47510B]/10 hover:bg-[#CAD23C]">
                      <CheckCircle2 size={20} />
                    </button>
                    <button className="p-3 rounded-xl bg-[#47510B] text-[#CAD23C] shadow-lg">
                      <Navigation size={20} strokeWidth={3} />
                    </button>
                  </div>
                )}
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* ADMIN VERIFICATION MODAL (Same as before but refined) */}
      {verifyingId && (
         <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 bg-[#47510B]/90 backdrop-blur-md">
           <div className="bg-[#FDFAD8] p-8 rounded-[50px] border-[10px] border-white w-full max-w-sm text-center animate-slide-up">
             <Database size={40} className="mx-auto text-[#47510B] mb-4 animate-bounce" />
             <h3 className="text-xl font-black uppercase italic text-[#47510B]">Syncing_Sensors</h3>
             <div className="my-6 p-6 bg-white rounded-3xl border-2 border-[#47510B]">
                <p className="text-[9px] font-black opacity-30 uppercase mb-2">Node Fill Level</p>
                <p className="text-5xl font-black text-[#AB1717]">12%</p>
             </div>
             <button onClick={() => setVerifyingId(null)} className="w-full py-4 bg-[#47510B] text-[#CAD23C] rounded-[20px] font-black uppercase text-sm">Confirm Completion</button>
           </div>
         </div>
      )}
    </div>
  );
};

export default ScheduleTab;
